package com.slss.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="quality_inspection_orders") public class QualityInspectionOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="source_scan_table_id",nullable=false,unique=true) Long sourceScanTableId; @Column(name="customer_name",nullable=false) String customerName; @Column(name="machine_model",nullable=false) String machineModel; int quantity; @Lob @Column(name="stages_json",nullable=false,columnDefinition="LONGTEXT") String stagesJson; String status="PENDING"; String createdBy; Instant createdAt=Instant.now(); public Long getId(){return id;} public Long getSourceScanTableId(){return sourceScanTableId;} public void setSourceScanTableId(Long v){sourceScanTableId=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public String getMachineModel(){return machineModel;} public void setMachineModel(String v){machineModel=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public String getStagesJson(){return stagesJson;} public void setStagesJson(String v){stagesJson=v;} public String getStatus(){return status;} public String getCreatedBy(){return createdBy;} public void setCreatedBy(String v){createdBy=v;} public Instant getCreatedAt(){return createdAt;} }
